transforms.code:
try:
	# Input
	import system
	ds = value  # BasicDataset o PyDataSet

	# Normaliza PyDataSet -> BasicDataset
	if "PyDataSet" in str(type(ds)):
		ds = system.dataset.toDataSet(ds)

	# Columnas e índice de "ID Corrida"
	cols = [ds.getColumnName(i) for i in range(ds.getColumnCount())]
	if "RunID" not in cols:
		return ds
	idx = cols.index("RunID")

	# Reconstruye filas cambiando -1 -> "NA" (la columna queda como str)
	rows = []
	for r in range(ds.getRowCount()):
		row = []
		for c in range(len(cols)):
			val = ds.getValueAt(r, c)
			if c == idx:
				row.append("NA" if val == -1 else ("" if val is None else str(val)))
			else:
				row.append(val)
		rows.append(row)

	# Output
	return system.dataset.toDataSet(cols, rows)

except:
	import system
	return system.dataset.toDataSet(["ID Corrida"], [["NA"]])

